package com.hbm.entity.mob.ufo;
import com.hbm.advancement.HbmAdvancements;import com.hbm.damage.HbmDamageSources;import com.hbm.entity.LegacyTrackingRange;import com.hbm.entity.mob.maskman.LegacyNpcBullets;import com.hbm.entity.projectile.EntityBulletBaseNT;import com.hbm.explosion.ExplosionNukeSmall;import com.hbm.exposure.HbmExposure;import com.hbm.registry.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.network.syncher.*;import net.minecraft.server.level.*;import net.minecraft.sounds.*;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.effect.MobEffects;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.monster.Enemy;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.Heightmap;import net.minecraft.world.phys.*;
/** Actual independent X5846 EntityUFO; the source does NOT inherit the separate unused EntityUFOBase. */
public final class EntityUFO extends FlyingMob implements Enemy,LegacyTrackingRange {
 private static final EntityDataAccessor<Boolean> BEAM=SynchedEntityData.defineId(EntityUFO.class,EntityDataSerializers.BOOLEAN);private static final EntityDataAccessor<Integer> WAY_X=SynchedEntityData.defineId(EntityUFO.class,EntityDataSerializers.INT),WAY_Y=SynchedEntityData.defineId(EntityUFO.class,EntityDataSerializers.INT),WAY_Z=SynchedEntityData.defineId(EntityUFO.class,EntityDataSerializers.INT);
 public int courseChangeCooldown,scanCooldown,hurtCooldown,beamTimer;private Entity target;private final List<Entity> secondaries=new ArrayList<>();private Entity xpKiller;private boolean pendingExperience;
 private final ServerBossEvent boss=new ServerBossEvent(getDisplayName(),BossEvent.BossBarColor.PURPLE,BossEvent.BossBarOverlay.PROGRESS);
 public EntityUFO(EntityType<? extends EntityUFO> type,Level level){super(type,level);xpReward=500;noCulling=true;deathTime=-30;}
 public static AttributeSupplier.Builder attributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,20000);}
 @Override public int legacyTrackingRange(){return 1000;}@Override protected void registerGoals(){}@Override public void checkDespawn(){}@Override public boolean shouldRenderAtSqrDistance(double d){return d<500000;}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(BEAM,false);b.define(WAY_X,0);b.define(WAY_Y,0);b.define(WAY_Z,0);}
 public void setWaypoint(int x,int y,int z){entityData.set(WAY_X,x);entityData.set(WAY_Y,y);entityData.set(WAY_Z,z);}public int waypointX(){return entityData.get(WAY_X);}public int waypointY(){return entityData.get(WAY_Y);}public int waypointZ(){return entityData.get(WAY_Z);}public void setBeam(boolean b){entityData.set(BEAM,b);}public boolean getBeam(){return entityData.get(BEAM);}
 public boolean canAttackClass(Class<?> type){return type!=getClass()&&type!=EntityBulletBaseNT.class;}
 @Override public boolean hurt(DamageSource source,float amount){if(hurtCooldown>0)return false;boolean hit=super.hurt(source,amount);if(hit)hurtCooldown=5;return hit;}
 @Override public void startSeenByPlayer(ServerPlayer player){super.startSeenByPlayer(player);boss.addPlayer(player);}@Override public void stopSeenByPlayer(ServerPlayer player){super.stopSeenByPlayer(player);boss.removePlayer(player);}@Override public void remove(RemovalReason reason){boss.removeAllPlayers();super.remove(reason);}
 @Override public void tick(){super.tick();if(!level().isClientSide){boss.setProgress(getHealth()/getMaxHealth());boss.setName(getDisplayName());}}
 @Override protected void customServerAiStep(){if(level().getDifficulty()==Difficulty.PEACEFUL){discard();return;}if(hurtCooldown>0)hurtCooldown--;if(courseChangeCooldown>0)courseChangeCooldown--;if(scanCooldown>0)scanCooldown--;if(target!=null&&!target.isAlive())target=null;
  if(scanCooldown<=0){secondaries.clear();target=null;for(var e:level().getEntities(this,getBoundingBox().inflate(100,50,100))){if(!e.isAlive()||!canAttackClass(e.getClass()))continue;if(e instanceof Player p){if(p.getAbilities().instabuild||p.isSpectator()||p.hasEffect(MobEffects.INVISIBILITY))continue;if(target==null||distanceToSqr(e)<distanceToSqr(target))target=e;}if(e instanceof LivingEntity&&distanceToSqr(e)<10000&&hasLineOfSight(e)&&e!=target)secondaries.add(e);}if(target==null&&!secondaries.isEmpty())target=secondaries.get(random.nextInt(secondaries.size()));scanCooldown=50;}
  if(target!=null&&courseChangeCooldown<=0){var delta=new Vec3(getX()-target.getX(),0,getZ()-target.getZ());if(random.nextInt(3)>0)delta=delta.yRot((float)Math.PI*2*random.nextFloat());double length=delta.length();int x=Mth.floor(target.getX()-delta.x/length*35),z=Mth.floor(target.getZ()-delta.z/length*35);setWaypoint(x,Math.max(surface(x,z)+20+random.nextInt(15),(int)target.getY()+15),z);courseChangeCooldown=40+random.nextInt(20);}
  if(beamTimer<=0&&getBeam())setBeam(false);if(target!=null&&Math.abs(target.getX()-getX())+Math.abs(target.getZ()-getZ())<25)beamTimer=30;
  if(beamTimer>0){beamTimer--;if(!getBeam()){playSound(HbmSounds.get("entity.ufoBeam"),10,1);setBeam(true);}int floor=beamFloor();if(floor<getY()){var area=new AABB(getX(),floor,getZ(),getX(),getY(),getZ()).inflate(5,0,5);for(var e:level().getEntities(this,area))if(canAttackClass(e.getClass())){e.hurt(HbmDamageSources.causeCombineDamage(this,e),1000);e.igniteForSeconds(5);if(e instanceof LivingEntity living)HbmExposure.contaminate(living,HbmExposure.Contamination.CREATIVE,5);}UfoGroundCloud.send(level(),getX(),floor+.5,getZ());var motion=getDeltaMovement();UfoGroundCloud.send(level(),getX()+motion.x*.5,floor+.5,getZ()+motion.z*.5);}}
  if(tickCount%300<200){if(tickCount%4==0)shootSelected(false);else if(tickCount%4==2&&target!=null)laserAttack(target);}else{if(tickCount%20==0)shootSelected(true);else if(tickCount%20==10&&target!=null)rocketAttack(target);}
  setDeltaMovement(Vec3.ZERO);if(courseChangeCooldown>0){var delta=new Vec3(waypointX()-getX(),waypointY()-getY(),waypointZ()-getZ());double length=delta.length(),speed=target instanceof Player?5:2;if(length>5){if(courseTraversable(length))setDeltaMovement(delta.scale(speed/length));else courseChangeCooldown=0;}}
 }
 private int surface(int x,int z){int top=level().getHeight(Heightmap.Types.WORLD_SURFACE,x,z);for(int y=top-1;y>=level().getMinBuildHeight();y--){var pos=new BlockPos(x,y,z);if(level().getBlockState(pos).getLightBlock(level(),pos)>0)return y+1;}return level().getMinBuildHeight();}
 /** Original literal non-air scan; extend its old0 lower bound to the actual modern build height. */
 public int beamFloor(){int x=Mth.floor(getX()),z=Mth.floor(getZ()),minimum=level().getMinBuildHeight();var pos=new BlockPos.MutableBlockPos();for(int y=Mth.ceil(getY());y>=minimum;y--)if(!level().getBlockState(pos.set(x,y,z)).isAir())return y;return minimum;}
 private void shootSelected(boolean rocket){if(!secondaries.isEmpty()){var e=secondaries.get(random.nextInt(secondaries.size()));if(!e.isAlive())secondaries.remove(e);else if(rocket)rocketAttack(e);else laserAttack(e);}else if(target!=null){if(rocket)rocketAttack(target);else laserAttack(target);}}
 private boolean courseTraversable(double length){double x=(waypointX()-getX())/length,y=(waypointY()-getY())/length,z=(waypointZ()-getZ())/length;var box=getBoundingBox();for(int i=1;i<length;i++){box=box.move(x,y,z);if(!level().noCollision(this,box))return false;}return true;}
 private void laserAttack(Entity e){var delta=new Vec3(getX()-e.getX(),0,getZ()-e.getZ()).yRot((float)Math.toRadians(-80+random.nextInt(160))).normalize();double x=getX()-delta.x*10,y=getY()+.5,z=getZ()-delta.z*10;var aim=new Vec3(e.getX()-x,e.getY()+e.getBbHeight()/2-y,e.getZ()-z).normalize();var bullet=new EntityBulletBaseNT(level(),LegacyNpcBullets.WORM_LASER);bullet.setThrower(this);bullet.setPos(x,y,z);bullet.setThrowableHeading(aim.x,aim.y,aim.z,2,.02F);level().addFreshEntity(bullet);playSound(HbmSounds.get("weapon.ballsLaser"),5,1);}
 private void rocketAttack(Entity e){var aim=new Vec3(e.getX()-getX(),e.getY()+e.getBbHeight()/2-getY()-.5,e.getZ()-getZ()).normalize();var bullet=new EntityBulletBaseNT(level(),LegacyNpcBullets.UFO_ROCKET);bullet.setThrower(this);bullet.setPos(getX(),getY()-.5,getZ());bullet.setThrowableHeading(aim.x,aim.y,aim.z,2,.02F);bullet.getPersistentData().putInt("homingTarget",e.getId());level().addFreshEntity(bullet);playSound(HbmSounds.get("turret.richard_fire"),5,1);}
 @Override protected void tickDeath(){if(getBeam())setBeam(false);setDeltaMovement(getDeltaMovement().add(0,-.05,0));if(deathTime==-10)playSound(HbmSounds.get("entity.chopperDamage"),10,1);if(deathTime==19&&!level().isClientSide){level().explode(this,getX(),getY(),getZ(),10,true,Level.ExplosionInteraction.BLOCK);ExplosionNukeSmall.explode(level(),getX(),getY(),getZ(),ExplosionNukeSmall.PARAMS_MEDIUM);for(var player:level().getEntitiesOfClass(Player.class,getBoundingBox().inflate(200),p->true)){if(player instanceof ServerPlayer server)HbmAdvancements.trigger(server,"bossUFO");player.getInventory().add(new ItemStack(HbmContent.item("coin_ufo")));}}super.tickDeath();if(deathTime==20&&!level().isClientSide&&pendingExperience){super.dropExperience(xpKiller);pendingExperience=false;}}
 /** Vanilla1.21 otherwise grants XP immediately; source grants it only at its final death frame. */
 @Override protected void dropExperience(Entity killer){xpKiller=killer;pendingExperience=true;}
 @Override protected float getSoundVolume(){return 10;}@Override protected SoundEvent getHurtSound(DamageSource source){return SoundEvents.BLAZE_HURT;}@Override protected SoundEvent getDeathSound(){return null;}@Override public SoundSource getSoundSource(){return SoundSource.HOSTILE;}
 // Source adds no NBT: inherited health/motion/deathTime persist; waypoints,scan,beam,hurt and targets reset.
}
